import hoverSoundSrc from "@/assets/sounds/hover.mp3";
import clickSoundSrc from "@/assets/sounds/click.mp3";

// Repris du pattern de l'installateur (installer/src/renderer.js) : chaque
// appel crée une NOUVELLE instance HTMLAudioElement plutôt que de rembobiner
// une instance partagée, pour que deux lectures qui se chevauchent (survol
// rapide de plusieurs boutons, ou clic pendant qu'un hover joue encore) ne
// s'interrompent jamais l'une l'autre.
const SOUND_FILES = {
  hover: hoverSoundSrc,
  click: clickSoundSrc,
} as const;

type UiSoundName = keyof typeof SOUND_FILES;

const VOLUME: Record<UiSoundName, number> = {
  hover: 0.35,
  click: 0.5,
};

const MUTE_STORAGE_KEY = "apex-ui-sound-muted";

// Coupés par défaut : seule la présence explicite de "false" dans le
// localStorage (l'utilisateur a déjà réactivé le son une fois) désactive le
// mute. Toute autre valeur (absente, "true", corrompue) => muet.
function readStoredMuted(): boolean {
  try {
    return localStorage.getItem(MUTE_STORAGE_KEY) !== "false";
  } catch {
    return true;
  }
}

let muted = readStoredMuted();
const listeners = new Set<(muted: boolean) => void>();

export function isUiSoundMuted() {
  return muted;
}

export function setUiSoundMuted(next: boolean) {
  muted = next;
  try {
    localStorage.setItem(MUTE_STORAGE_KEY, String(next));
  } catch {
    // no-op : localStorage indisponible (navigation privée, quota...).
  }
  listeners.forEach((listener) => listener(muted));
}

export function toggleUiSoundMuted() {
  setUiSoundMuted(!muted);
}

export function subscribeUiSoundMuted(listener: (muted: boolean) => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function playUiSound(name: UiSoundName) {
  if (muted) return;
  const src = SOUND_FILES[name];
  if (!src) return;
  try {
    const audio = new Audio(src);
    audio.volume = VOLUME[name];
    // Le play() peut être rejeté (ex. avant toute interaction utilisateur) -
    // on ignore silencieusement, ce n'est jamais critique pour l'UI.
    void audio.play().catch(() => {});
  } catch {
    // no-op : environnement sans Audio (SSR, tests) ou source indisponible.
  }
}
import { useEffect, useState } from "react";
import {
  playUiSound,
  isUiSoundMuted,
  toggleUiSoundMuted,
  subscribeUiSoundMuted,
} from "@/utils/uiSound";

// Sélecteur des éléments interactifs "génériques" de l'UI : boutons, liens,
// éléments avec un rôle de bouton/menu, inputs cliquables, et tout élément
// marqué explicitement avec data-ui-sound (pour les cas custom qui ne
// matchent aucun des sélecteurs ci-dessus, ou pour désactiver via
// data-ui-sound="off").
const INTERACTIVE_SELECTOR = [
  "button",
  "a[href]",
  "[role='button']",
  "[role='menuitem']",
  "[role='tab']",
  "[role='switch']",
  "[role='checkbox']",
  "[role='radio']",
  "input[type='checkbox']",
  "input[type='radio']",
  "input[type='range']",
  "[data-ui-sound]",
].join(",");

function findInteractiveTarget(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) return null;
  const el = target.closest<HTMLElement>(INTERACTIVE_SELECTOR);
  if (!el) return null;
  if (el.dataset.uiSound === "off") return null;
  if (el.hasAttribute("disabled") || el.getAttribute("aria-disabled") === "true") {
    return null;
  }
  return el;
}

/**
 * Branche les sons de survol et de clic sur tous les éléments interactifs de
 * l'interface via délégation d'événements sur `document`, plutôt que
 * d'ajouter des handlers à chaque composant un par un - cohérent avec le
 * bus d'événements global `apex-*` déjà utilisé entre Viewport3D et les
 * panneaux (voir CLAUDE.md), on évite ici aussi de faire du prop drilling.
 *
 * À monter une seule fois, au niveau racine de l'app (voir App.tsx).
 */
export function useUiSounds() {
  useEffect(() => {
    let lastHoverTarget: HTMLElement | null = null;

    const handlePointerOver = (event: PointerEvent) => {
      const el = findInteractiveTarget(event.target);
      if (!el || el === lastHoverTarget) return;
      lastHoverTarget = el;
      playUiSound("hover");
    };

    const handlePointerOut = (event: PointerEvent) => {
      const el = findInteractiveTarget(event.target);
      if (el && el === lastHoverTarget) {
        lastHoverTarget = null;
      }
    };

    const handleClick = (event: MouseEvent) => {
      const el = findInteractiveTarget(event.target);
      if (!el) return;
      playUiSound("click");
    };

    document.addEventListener("pointerover", handlePointerOver);
    document.addEventListener("pointerout", handlePointerOut);
    document.addEventListener("click", handleClick);

    return () => {
      document.removeEventListener("pointerover", handlePointerOver);
      document.removeEventListener("pointerout", handlePointerOut);
      document.removeEventListener("click", handleClick);
    };
  }, []);
}

/**
 * Expose l'état mute/unmute des sons UI (coupés par défaut) et une fonction
 * pour le basculer, pour un bouton du type de celui de FileSidebar.
 */
export function useUiSoundMuted() {
  const [muted, setMuted] = useState(isUiSoundMuted);

  useEffect(() => subscribeUiSoundMuted(setMuted), []);

  return [muted, toggleUiSoundMuted] as const;
}
